    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy, x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 2 and q not in seen:
                        seen.add(q)
                        stack.append(q)
            comps.append((min(x for y,x in cells), min(y for y,x in cells), cells))
    comps.sort(key=lambda z: (z[0], z[1]))
    out = [row[:] for row in grid]
    if not comps:
        return out
    # The leftmost object establishes the alternating sequence; a multi-block
    # vertical object starts with the highlighted color, while a single square
    # follows the parity of its row.
    x0, y0, cells0 = comps[0]
    start_highlighted = len(cells0) > 4 or y0 % 2 == 0
    for i, (_, _, cells) in enumerate(comps):
        highlighted = (i % 2 == 0) == start_highlighted
        if highlighted:
            for y, x in cells:
                out[y][x] = 8
    return out
